/**
 * Module 2: Myth-Busting
 *
 * Shatters the 9 financial myths that destroy wealth.
 * Covers hidden fees, the Fee Destruction Formula, and the power of index funds.
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTrainingStore } from '../../../../stores/trainingStore';
import { createSanitizedMarkup } from '../../../../lib/utils/sanitizeHtml';
import type { ScreenContent, QuizOption } from '../types';

const MODULE_2_SCREENS: ScreenContent[] = [
  {
    id: 'intro',
    type: 'intro',
    title: 'Welcome to Module 2: Myth-Busting',
    subtitle: 'Shatter the 9 Financial Myths That Destroy Wealth',
  },
  {
    id: 'nine-myths',
    type: 'content',
    title: 'The 9 Financial Myths',
    subtitle: 'What the Wall Street machine wants you to believe',
  },
  {
    id: 'fee-destruction',
    type: 'content',
    title: 'The Fee Destruction Formula',
    subtitle: 'How tiny fees compound into massive losses',
  },
  {
    id: 'myth-quiz',
    type: 'quiz',
    title: 'Test Your Knowledge',
    question: 'Which statement about mutual fund fees is TRUE?',
    options: [
      { value: 'a', label: 'A 1% fee is negligible', feedback: 'False! A 1% fee can reduce wealth by 30% over 40 years.', isCorrect: false },
      { value: 'b', label: 'Index funds have lower fees', feedback: 'Correct! Index funds average 0.1-0.5%, active funds 1-2%.', isCorrect: true },
      { value: 'c', label: 'High fees mean better performance', feedback: 'False! High-fee funds consistently underperform.', isCorrect: false },
      { value: 'd', label: 'Fees only charged on profits', feedback: 'False! Fees charged on all assets regardless of performance.', isCorrect: false },
    ],
    correctAnswer: 'b',
  },
  {
    id: 'index-scenario',
    type: 'scenario',
    title: 'Investment Decision',
    scenario: 'Your 401(k) offers two options:\n\nOption A: Active fund with 1.5% fee\nOption B: Index fund with 0.1% fee\n\nYou have 35 years until retirement.',
    question: 'What do you choose?',
    options: [
      { value: 'active', label: 'Choose active fund', feedback: 'Past performance ≠ future results. The 1.4% fee difference could cost you 30-40% of your wealth.', isCorrect: false },
      { value: 'index', label: 'Choose index fund', feedback: 'Wise choice! Avoiding the fee drag could mean 2-3x more wealth at retirement.', isCorrect: true },
      { value: 'split', label: 'Split between both', feedback: 'Half your money still suffers high fees. Consider 100% index fund.', isCorrect: false },
    ],
    correctAnswer: 'index',
  },
  {
    id: 'reflection',
    type: 'reflection',
    title: 'Personal Reflection',
    content: 'Think about your current investments. Do you know what fees you\'re paying?\n\nReflect on:\n- What surprised you about fees?\n- Will you check your investment fees?\n- What action will you take?',
  },
  {
    id: 'complete',
    type: 'content',
    title: 'Module 2 Complete!',
    subtitle: 'You\'re now armed with the truth about fees',
  },
];

function getScreenContent(screen: ScreenContent): string {
  const defaults: Record<string, string> = {
    'nine-myths': `
<h2>The 9 Financial Myths Tony Robbins Identified:</h2>
<ol class="list-decimal ml-8 space-y-2">
<li><strong>"Investing is complicated"</strong> - Myth! Simple index funds outperform 80% of pros.</li>
<li><strong>"Advisors are fiduciaries"</strong> - Most are brokers who put commissions first.</li>
<li><strong>"Fees don't matter"</strong> - A 2% fee can cost you 65% of your wealth.</li>
<li><strong>"My fund beat the market"</strong> - Past performance NEVER predicts results.</li>
<li><strong>"High fees = better service"</strong> - You're paying for marketing, not performance.</li>
</ol>
`,
    'fee-destruction': `
<h2>The Fee Destruction Formula</h2>
<p>The math is brutal: <strong>Higher fees = exponentially less wealth.</strong></p>
<p>Starting with $100,000, earning 7% annually over 40 years:</p>
<ul class="list-disc ml-8 space-y-1">
<li><strong>0.1% fee</strong> → $1,497,000 final wealth</li>
<li><strong>1% fee</strong> → $1,075,000 (lose $422,000!)</li>
<li><strong>2% fee</strong> → $747,000 (lose $750,000!)</li>
</ul>
<p class="mt-4 text-primary-teal font-semibold">A 1% fee difference = HALF your wealth gone.</p>
`,
    'complete': `
<h2 class="text-green-400">🎉 Congratulations!</h2>
<p>You've completed Module 2: Myth-Busting.</p>
<h3 class="mt-4">Key Takeaways:</h3>
<ul class="list-disc ml-8 space-y-1">
<li>You know the 9 financial myths that destroy wealth</li>
<li>You understand the Fee Destruction Formula</li>
<li>You can spot fee traps in investment products</li>
<li>You know index funds outperform most active funds</li>
</ul>
`,
  };
  return defaults[screen.id] || screen.content || '';
}

export default function Module2_MythBusting() {
  const navigate = useNavigate();
  const { startModule, recordScreenProgress, completeModule } = useTrainingStore();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showFeedback, setShowFeedback] = useState(false);

  const currentScreenData = MODULE_2_SCREENS[currentIndex];
  const totalScreens = MODULE_2_SCREENS.length;
  const moduleId = 'module-2-mythbusting';

  useEffect(() => {
    startModule(moduleId);
  }, [moduleId, startModule]);

  const handleAnswerSelect = (answer: string) => {
    setSelectedAnswer(answer);
    setShowFeedback(true);
  };

  const handleNext = () => {
    recordScreenProgress(moduleId, currentScreenData.id, totalScreens);
    const nextIndex = currentIndex + 1;
    if (nextIndex < totalScreens) {
      setCurrentIndex(nextIndex);
      setSelectedAnswer(null);
      setShowFeedback(false);
    } else {
      completeModule(moduleId);
      navigate('/training/hub');
    }
  };

  const handleBack = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setSelectedAnswer(null);
      setShowFeedback(false);
    } else {
      navigate('/training/hub');
    }
  };

  const progress = ((currentIndex + 1) / totalScreens) * 100;

  return (
    <div className="min-h-screen bg-gradient-to-br from-dark-bg to-dark-surface py-12 px-4">
      <div className="max-w-4xl mx-auto">
        {/* Progress Bar */}
        <div className="mb-6">
          <div className="flex justify-between text-sm text-gray-400 mb-2">
            <span>Progress</span>
            <span>{Math.round(progress)}%</span>
          </div>
          <div className="w-full bg-dark-bg rounded-full h-2">
            <div className="bg-primary-teal h-2 rounded-full transition-all" style={{ width: `${progress}%` }} />
          </div>
        </div>

        {/* Screen Content */}
        <div className="bg-dark-surface border border-dark-border rounded-lg p-8">
          {/* Title */}
          {currentScreenData.title && (
            <h1 className="text-3xl font-bold text-white mb-2">{currentScreenData.title}</h1>
          )}
          {currentScreenData.subtitle && (
            <p className="text-xl text-primary-teal mb-6">{currentScreenData.subtitle}</p>
          )}

          {/* Content */}
          {(currentScreenData.type === 'content' || currentScreenData.type === 'intro' || currentScreenData.type === 'reflection') && (
            <div className="text-gray-300 leading-relaxed prose prose-invert max-w-none"
              dangerouslySetInnerHTML={createSanitizedMarkup(getScreenContent(currentScreenData))} />
          )}

          {/* Quiz/Scenario Options */}
          {(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && currentScreenData.options && (
            <div className="mt-8 space-y-3">
              {currentScreenData.options.map((option: QuizOption) => (
                <button
                  key={option.value}
                  onClick={() => handleAnswerSelect(option.value)}
                  disabled={showFeedback}
                  className={`w-full text-left px-6 py-4 rounded-lg border transition-all ${
                    selectedAnswer === option.value
                      ? showFeedback && option.isCorrect
                        ? 'bg-green-400/20 border-green-400'
                        : showFeedback
                        ? 'bg-red-400/20 border-red-400'
                        : 'bg-primary-teal/20 border-primary-teal'
                      : 'bg-dark-bg border-dark-border hover:border-primary-teal'
                  } ${showFeedback ? 'cursor-default' : 'hover:bg-primary-teal/10'}`}
                >
                  <span className="text-gray-200 font-semibold">{option.label}</span>
                </button>
              ))}
            </div>
          )}

          {/* Feedback */}
          {showFeedback && selectedAnswer && currentScreenData.options && (
            <div className={`mt-6 p-4 rounded-lg border ${
              selectedAnswer === currentScreenData.correctAnswer
                ? 'bg-green-400/10 border-green-400/30'
                : 'bg-red-400/10 border-red-400/30'
            }`}>
              <p className="text-gray-300">
                {currentScreenData.options.find((o: QuizOption) => o.value === selectedAnswer)?.feedback || ''}
              </p>
            </div>
          )}

          {/* Navigation */}
          {(currentScreenData.type === 'intro' || currentScreenData.type === 'content' ||
            currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack}
                className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 hover:text-white transition-colors font-semibold">
                ← Back
              </button>
              <button onClick={handleNext}
                disabled={(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && !showFeedback}
                className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold transition-colors disabled:bg-gray-700 disabled:cursor-not-allowed">
                {currentIndex === totalScreens - 1 ? 'Complete' : 'Next'} →
              </button>
            </div>
          )}

          {/* Reflection Navigation */}
          {currentScreenData.type === 'reflection' && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack}
                className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 hover:text-white transition-colors font-semibold">
                ← Back
              </button>
              <button onClick={handleNext}
                className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold transition-colors">
                Continue →
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
